/**
 * Accessories and spare parts.
 *
 * NOTHING HERE IS INVENTED. Every entry is a component the V-Tech Aqua 2023
 * catalogue names in the cartridge or bill-of-materials line of a system we
 * list, and `fits` is the set of models that actually name it — derived, not
 * written by hand. Generated by tools/gen_accessories.py; edit that pipeline
 * rather than this file.
 *
 * There are no prices. The catalogue prices complete systems and never prices a
 * part on its own, so every accessory is quoted on request rather than carrying
 * a guessed figure.
 *
 * There are no photographs either — the catalogue does not picture its parts, so
 * cards draw a category glyph instead of a stock image.
 */
import { products, sections } from './products'

export const CATEGORIES = [
  { id: 'filter-cartridges', label: 'Filter Cartridges', blurb: 'Replaceable cartridge stages — sediment, carbon, UF, UV, alkaline and post-RO polishing.' },
  { id: 'ro-membranes', label: 'RO Membranes', blurb: 'The reverse osmosis elements that do the actual salt rejection.' },
  { id: 'pumps', label: 'Pumps', blurb: 'Feed and high-pressure pumps that move and pressurise the water.' },
  { id: 'controls-instrumentation', label: 'Controls & Instrumentation', blurb: 'Controllers, panels, gauges and meters — from the domestic TDS control to plant instrumentation.' },
  { id: 'membrane-pressure-tubes', label: 'Membrane Pressure Tubes', blurb: 'Pressure vessels that hold RO membrane elements at operating pressure.' },
  { id: 'filter-housings', label: 'Filter Housings', blurb: 'Jumbo housings that carry the large pre-filter cartridges.' },
  { id: 'frp-vessels', label: 'FRP Vessels', blurb: 'Fibre-reinforced plastic vessels for pre-treatment media beds.' },
  { id: 'filter-media', label: 'Filter Media', blurb: 'Loose media that fills the pre-treatment vessels.' },
  { id: 'valves-fittings', label: 'Valves & Fittings', blurb: 'Multiport and solenoid valves, plus the pipework fittings that connect them.' },
]

const CATEGORY_LABEL = Object.fromEntries(CATEGORIES.map((c) => [c.id, c.label]))

/**
 * `kind` marks these apart from systems so the shared enquiry list can render a
 * part without reaching for a photograph or a product page; `price: null` makes
 * them read as "Price on request" through the same formatter the unpriced
 * catalogue models already use.
 */
const part = (a) => ({
  ...a,
  kind: 'accessory',
  price: null,
  configuration: CATEGORY_LABEL[a.category],
})

